import{_ as t,o as a,c as s,an as n}from"./chunks/framework.lEm9Znpx.js";const m=JSON.parse('{"title":"What is GoMeta?","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/what-is-gometa.md","filePath":"concepts/what-is-gometa.md","lastUpdated":null}'),o={name:"concepts/what-is-gometa.md"};function i(r,e,l,c,d,p){return a(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="What-is-GoMeta?" tabindex="-1">What is <span class="gm-name">GoMeta</span>? <a class="header-anchor" href="#What-is-GoMeta?" aria-label="Permalink to &quot;What is GoMeta? {#What-is-GoMeta?}&quot;">​</a></h1><p><span class="gm-name">GoMeta.jl</span> is an <em>interpretable-metadata</em> engine for source files, written in Julia. A file carries its ordinary content plus <code>#~</code> <strong>metaLines</strong> — comment lines with machine-interpretable metadata (labels, visibility actions, conditions) sitting right beside the content they describe.</p><p><span class="gm-name">GoMeta</span> <strong>absorbs</strong> the metaLines, <strong>evaluates</strong> which <em>alterants</em> apply to each piece of content, and a renderer <strong>applies</strong> the result:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light-high-contrast github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>parse (BLS) → absorb (read metaLines) → evaluate (which alterants apply) → render (apply Visib)</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title"><span class="gm-name">GoMeta</span> evaluates — it never executes</p><p>Conditions run in <span class="gm-name">GoMeta</span>&#39;s own closed interpreter, never through Julia&#39;s <code>eval</code>. A metaLine can describe, label, and select; it cannot run anything. (One deliberate, explicitly opt-in extension mode exists — see the SECURITY notes in the repository.)</p></div><h2 id="Why-metadata-—-and-why-in-comments?" tabindex="-1">Why metadata — and why in comments? <a class="header-anchor" href="#Why-metadata-—-and-why-in-comments?" aria-label="Permalink to &quot;Why metadata — and why in comments? {#Why-metadata-—-and-why-in-comments?}&quot;">​</a></h2><ul><li><p><strong>One source file, many output formats.</strong> A file never has to be forked per audience: in this release, one marked Julia source file derives four notebook editions (full · student · report · slides) plus one executed twin, a pair of Documenter manual pages generated as views of the same source — and, as for every file <span class="gm-name">GoMeta</span> processes, the share-view render of the file itself.</p></li><li><p><strong>Webs instead of hierarchies.</strong> A folder tree or a chapter outline forces each item into a single position — a stringent limitation. Labels weave webs of meaning instead: the same piece of content carries as many labels as apply, and one query brings it back (the shipped <code>find_by_label.jl</code> demo answers &quot;which cells carry <code>:label5</code>?&quot; over the committed corpus).</p></li><li><p><strong>Language-agnostic, because comments.</strong> The metadata hides inside ordinary comments, so the host language never sees it — and the same idea travels beyond Julia: <code>0.3.0</code> ships three content flavors, <code>:julia</code> (the <code>#</code> comment lead, the default), <code>:c</code> (the <code>//</code> line-comment family), and <code>:latex</code> (<code>%</code>) — selected explicitly, never inferred.</p></li></ul><h2 id="The-idea" tabindex="-1">The idea <a class="header-anchor" href="#The-idea" aria-label="Permalink to &quot;The idea {#The-idea}&quot;">​</a></h2><ol><li><p><strong>Embed</strong> formalized meaning [metadata] into comments — brief, simple, expressive, extendable metadata riding where every language already has room.</p></li><li><p><strong>Absorb &amp; evaluate</strong> — <span class="gm-name">GoMeta</span> absorbs that metadata (parses and interprets it) and evaluates which alterants apply to each piece of content, producing the evaluated values: the <strong>evals</strong> (evaluated metadata — unrelated to Julia&#39;s <code>eval</code>).</p></li><li><p><strong>Pass the evaluations on</strong> — the evals are the deliverable. <strong>Extensions</strong> — scripts, downstream tools, consumer packages — read them and act; <span class="gm-name">GoMeta</span>&#39;s own renderer, which applies <strong>Visib</strong> to produce the share-view, is simply the act built in.</p></li></ol><h2 id="What-it-is-for" tabindex="-1">What it is for <a class="header-anchor" href="#What-it-is-for" aria-label="Permalink to &quot;What it is for {#What-it-is-for}&quot;">​</a></h2><p>Everything in <span class="gm-name">GoMeta</span> serves four concrete uses of your accumulated files:</p><ol><li><p><strong>Find it again</strong> — name and tag a file where it lives, and retrieve it by meaning later.</p></li><li><p><strong>Link and swap</strong> — files reference each other by meaning, not by path.</p></li><li><p><strong>One source, many outputs</strong> — render the same file into different views without forking it.</p></li><li><p><strong>Share on your terms</strong> — strip what is private and publish the rest, by applying one simple function to <span class="gm-name">GoMeta</span>&#39;s output.</p></li></ol><h2 id="The-pieces" tabindex="-1">The pieces <a class="header-anchor" href="#The-pieces" aria-label="Permalink to &quot;The pieces {#The-pieces}&quot;">​</a></h2><ul><li><p>Before <span class="gm-name">GoMeta</span> can absorb and evaluate anything, <strong>BLS</strong> parses the file into a tree of <strong>Components</strong>: <strong>File → Block → Line → Segment</strong>. Every Component carries one of three flavors — <strong>Meta</strong>, <strong>Text</strong>, or <strong>Code</strong>: a line is Meta if it starts with a delimited <code>#~</code> head (<code>#~</code> followed by whitespace, a depth marker, or end of line), Code if it is executable source, Text otherwise.</p></li><li><p><strong>Every flavor can carry comments.</strong> A <code>##</code> opens a human comment whether the line is meta, text, or code — the comment rides its own Segment, and on a metaLine the meta-parser ignores it.</p></li><li><p>A <strong>metaBlock</strong> — one or more contiguous metaLines — is the unit that carries metadata scope for the content attached below it.</p></li><li><p>An <strong>alterant</strong> is a directive <span class="gm-name">GoMeta</span> applies to a Component. The <strong>Visib</strong> (visibility) alterant decides each Component&#39;s fate when rendered: <strong>show</strong>, <strong>hide</strong>, or <strong>discard</strong>.</p></li><li><p><strong>State-refs</strong> are built-in predicates (<code>isCode</code>, <code>isText</code>, <code>isMeta</code>, <code>containsMeta</code>) used inside <code>{ … }</code> conditions to decide whether an alterant applies.</p></li></ul><p>Continue with <a href="./metalines">metaLines</a> for the syntax, or jump straight to <a href="./../tutorials/getting-started">Getting started</a>.</p><h2 id="Status" tabindex="-1">Status <a class="header-anchor" href="#Status" aria-label="Permalink to &quot;Status {#Status}&quot;">​</a></h2><p><span class="gm-name">GoMeta.jl</span> <code>0.3.2</code> is <strong>alpha</strong>: a working, tested engine for the <strong>v0 subset</strong> of the <span class="gm-name">GoMeta</span> language. The committed example corpus — seven input/output pairs — renders <strong>byte-identically</strong> under the shipped 1140-test suite, and malformed or extreme input on the witnessed metaLine action surface receives a stable, documented refusal (the few remaining edges — including one documented crash edge — are catalogued honestly in the repository&#39;s API reference). The language grows by design; the v0 subset forecloses none of it.</p><p><span class="gm-name">GoMeta</span> is <strong>Fair Source</strong> — licensed under the Functional Source License, Version 1.1, MIT Future License (<strong>FSL-1.1-MIT</strong>; source-available, not OSI-approved open source): free for everyone&#39;s own use — at work, at university, in the public sector — including internal use and access, non-commercial education and research, and professional services provided to other licensees. Not licensed: offering <span class="gm-name">GoMeta</span> to others in a commercial product or service that competes with it or with the Licensor&#39;s own <span class="gm-name">GoMeta</span>-based offerings (for that, contact hello@gometa.dev). Each release automatically becomes <strong>MIT-licensed</strong> on its second anniversary. See the <a href="https://github.com/gometa-jl/GoMeta.jl" target="_blank" rel="noreferrer">repository</a> for the LICENSE file and details.</p>',18)])])}const g=t(o,[["render",i]]);export{m as __pageData,g as default};
